// AUTO-IA-12 — isolated, manually triggered, 100% synthetic workflow.
const event = Object.freeze({
  schema: 'AUTO_IA_DEMO_EVENT_V1',
  product: 'imagine-comercial',
  operation: 'funnel.calculate',
  tenant_ref: 'SYNTHETIC_TENANT_DEMO',
  event_ref: 'SYNTHETIC_EVENT_DEMO',
  weekly_visits: 120,
  lead_rate_percent: 10,
  customer_rate_percent: 20,
});
if (!event.tenant_ref.startsWith('SYNTHETIC_') || event.operation !== 'funnel.calculate') {
  throw new Error('AUTO_IA_12_CLOSED_FIXTURE_REQUIRED');
}
const projected_leads = Math.round(event.weekly_visits * event.lead_rate_percent / 100);
const projected_customers = Math.round(projected_leads * event.customer_rate_percent / 100);
return [{
  json: {
    schema: 'AUTO_IA_DEMO_RESULT_V1',
    decision: 'NO_AI',
    tenant_ref: event.tenant_ref,
    event_ref: event.event_ref,
    visits: event.weekly_visits,
    projected_leads,
    projected_customers,
    ai_api_calls: 0,
    ai_tokens: 0,
    commercial_credits_debited: 0,
    operational_authorization: false,
    mode: 'SYNTHETIC_MANUAL_ONLY',
  }
}];
